	PROJECT_INITIAL = 'PROJECT_INITIAL',
	PROJECT_RESTORE = 'PROJECT_RESTORE',
	PROJECT_FIX_CHANGE = 'PROJECT_FIX_CHANGE',
	PROJECT_UI_PATCH = 'PROJECT_UI_PATCH',
	PROJECT_CREATE_COMPONENT_FROM_PROMPT = 'PROJECT_CREATE_COMPONENT_FROM_PROMPT',
	PROJECT_CREATE_COMPONENT_FROM_PROMPT_AND_CODE = 'PROJECT_CREATE_COMPONENT_FROM_PROMPT_AND_CODE',
	PROJECT_DELETION = 'PROJECT_DELETION',
	PROJECT_TEXT_CHANGE = 'PROJECT_TEXT_CHANGE',
